mapper.update:
UPDATE TB_PAPSP01
   SET RC_ID           = #{payment.rechargingId}
      ,REMOTE_START_ID = #{payment.remoteStartId}
      ,CP_ID           = #{payment.cpId}
      ,CS_ID           = #{payment.csId}
      ,EVSE_ID         = #{payment.evseId}
      ,CARD_BIN        = #{payment.cardBin}
      ,CARD_LAST4      = #{payment.cardLast4}
      ,CARDHOLDER_NM   = #{payment.cardholderNm}
      ,AUTH_AMOUNT     = #{payment.authAmount}
      ,MAX_COST        = #{payment.maxCost}
      ,MAX_ENERGY      = #{payment.maxEnergy}
      ,SETTLED_AMOUNT  = #{payment.settledAmount}
      ,CURRENCY        = #{payment.currency}
      ,STATUS_CD       = #{payment.statusCd}
      ,REASON_CD       = #{payment.reasonCd}
      ,AUTH_DT         = #{payment.authDate}
      ,STARTED_DT      = #{payment.startedDate}
      ,SETTLED_DT      = #{payment.settledDate}
      ,CANCELED_DT     = #{payment.canceledDate}
      ,RECEIPT_URL     = #{payment.receiptUrl}
      ,RECEIPT_ID      = #{payment.receiptId}
      ,PSP_PROVIDER    = #{payment.pspProvider}
      ,EXTRA_INFO      = #{payment.extraInfo}
      ,UPD_DT          = #{payment.writer.updateDate}
      ,UPD_ID          = #{payment.writer.updUserId}
 WHERE PSP_REF = #{payment.pspRef}

UPDATE TB_PAPSP01
   SET STATUS_CD = #{statusCd}
      ,REASON_CD = #{reasonCd}
      ,UPD_DT    = NOW()
      ,UPD_ID    = #{updUserId}
 WHERE PSP_REF = #{pspRef}

UPDATE TB_PAPSP01
   SET RC_ID      = #{rechargingId}
      ,STARTED_DT = #{startedDate}
      ,STATUS_CD  = 'STARTED'
      ,UPD_DT     = NOW()
      ,UPD_ID     = #{updUserId}
 WHERE PSP_REF = #{pspRef}

UPDATE TB_PAPSP01
   SET SETTLED_AMOUNT = #{settledAmount}
      ,RECEIPT_URL    = #{receiptUrl}
      ,RECEIPT_ID     = #{receiptId}
      ,SETTLED_DT     = #{settledDate}
      ,STATUS_CD      = 'SETTLED'
      ,UPD_DT         = NOW()
      ,UPD_ID         = #{updUserId}
 WHERE PSP_REF = #{pspRef}

UPDATE TB_PAPSP01
   SET REASON_CD   = #{reasonCd}
      ,CANCELED_DT = #{canceledDate}
      ,STATUS_CD   = 'CANCELED'
      ,UPD_DT      = NOW()
      ,UPD_ID      = #{updUserId}
 WHERE PSP_REF = #{pspRef}
